    wp_ch6_s5_title: "6.5 Progettazione Dettagliata di NEA",
    wp_ch6_s5_p1: "NEA (Neo Energy Asset) è il token di mappaggio di asset di potenza di calcolo, emissione dinamica, distruzione di asset comporta distruzione di token.",
    wp_ch6_s5_mining: "Mappaggio di miner fisici: 60%",
    wp_ch6_s5_stake: "Generazione tramite staking di potenza di calcolo: 25%",
    wp_ch6_s5_partner: "Organizzazioni partner: 10%",
